-- Masuk initial cloud data. Apply only to the confirmed NEW empty project.
-- Current website remains a local demo until real auth/shared-write adapters are connected.
begin;
create table public.locations (
  id text primary key default gen_random_uuid()::text,
  name text not null check (length(btrim(name)) between 1 and 150),
  area text not null,
  address text not null,
  latitude double precision check (latitude between -85 and 85),
  longitude double precision check (longitude between -180 and 180),
  entrance_note text not null default '',
  difficulty_level smallint not null default 0 check (difficulty_level between 0 and 5),
  entry_requirements jsonb not null default '{}'::jsonb,
  tips text not null default '',
  maps_url text,
  source_url text,
  source_label text,
  last_modified_by text not null default '公开资料导入',
  verified_count integer not null default 0 check (verified_count >= 0),
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);
alter table public.locations enable row level security;
create policy "public location reading" on public.locations for select to anon, authenticated using (true);
grant select on public.locations to anon, authenticated;
-- No anonymous or demo-user writes. Shared writes require real authentication/version checks.
create index locations_area_idx on public.locations(area);
create index locations_updated_at_idx on public.locations(updated_at desc);
comment on column public.locations.difficulty_level is '0=待确认;公开资料不等于司机实测';

